concepts.code_exemple:
SELECT produit, id, quantite,
       RANK() OVER (
         PARTITION BY produit
         ORDER BY quantite DESC
       ) AS rang
FROM ventes;

SELECT date, quantite,
       SUM(quantite) OVER (ORDER BY date) AS cumul
FROM ventes;

SELECT p.produit
FROM produits p
WHERE NOT EXISTS (
  SELECT 1 FROM ventes v
  WHERE v.produit = p.produit
);
